content_text:
# HMAC-SHA256 Webhook Signature Middleware

Key point: **you must verify against the raw body bytes**, not a re-serialized parsed body — JSON key reordering or whitespace changes break the signature.

```javascript
const crypto = require('crypto');

function verifyWebhookSignature(options) {
  const {
    secret,                    // shared secret, from env/config — never hardcode
    headerName = 'x-signature',
    toleranceSeconds = 300,    // reject stale timestamps (replay protection)
  } = options;

  return (req, res, next) => {
    // 1. Raw body must be captured BEFORE body-parser runs
    //    (e.g. express.raw({ type: 'application/json' }) on this route)
    const rawBody = req.rawBody;
    if (!rawBody || rawBody.length === 0) {
      return res.status(400).json({ error: 'Missing body' });
    }

    // 2. Signature header must exist
    const sigHeader = req.get(headerName);
    if (!sigHeader) {
      return res.status(401).json({ error: 'Missing signature' });
    }

    // 3. Parse "t=<timestamp>,v1=<hex>" style header (Stripe-like format)
    const parts = Object.fromEntries(
      sigHeader.split(',').map(p => p.split('=').map(s => s.trim()))
    );
    const timestamp = parts.t;
    const receivedSig = parts.v1;

    if (!timestamp || !receivedSig) {
      return res.status(401).json({ error: 'Malformed signature header' });
    }

    // 4. Replay protection — reject old timestamps
    const age = Math.abs(Date.now() / 1000 - Number(timestamp));
    if (!Number.isFinite(Number(timestamp)) || age > toleranceSeconds) {
      return res.status(401).json({ error: 'Timestamp outside tolerance' });
    }

    // 5. Compute expected signature over `${timestamp}.${rawBody}`
    const payload = Buffer.concat([
      Buffer.from(`${timestamp}.`),
      Buffer.isBuffer(rawBody) ? rawBody : Buffer.from(rawBody),
    ]);
    const expected = crypto
      .createHmac('sha256', secret)
      .update(payload)
      .digest('hex');

    // 6. Timing-safe comparison — never use ===
    const a = Buffer.from(expected, 'hex');
    const b = Buffer.from(receivedSig, 'hex');
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    next();
  };
}

module.exports = { verifyWebhookSignature };
```

## Wiring it up

```javascript
app.use('/webhooks',
  express.raw({ type: 'application/json', limit: '1mb' }), // preserves raw bytes
  (req, res, next) => { req.rawBody = req.body; next(); },
  verifyWebhookSignature({ secret: process.env.WEBHOOK_SECRET }),
  express.json(), // now parse for the handler
  webhookHandler
);
```

## Security notes

- **Raw body only** — verify before any parsing/normalization.
- **`crypto.timingSafeEqual`** — prevents timing side channels; length check first since it throws on mismatch.
- **Timestamp in signed payload** — binds the signature to a time window, mitigating replay attacks.
- **Constant secret lookup** — load from env/KMS; rotate by accepting multiple valid secrets during rotation if needed.
- **Fail closed** — any missing/malformed element returns 401, never falls through.
- If your provider uses a different scheme (e.g., bare hex signature, no timestamp), adapt steps 3–5 but keep the raw-body and timing-safe-compare requirements.

The sketch already implements exactly that scheme — here's the confirmation of those three requirements as coded:

**1. Signed payload = `timestamp + '.' + raw_body`**

```javascript
const payload = Buffer.concat([
  Buffer.from(`${timestamp}.`),
  Buffer.isBuffer(rawBody) ? rawBody : Buffer.from(rawBody),
]);
const expected = crypto.createHmac('sha256', secret).update(payload).digest('hex');
```

**2. Reject timestamps older than five minutes**

```javascript
const toleranceSeconds = 300; // 5 minutes

const age = Math.abs(Date.now() / 1000 - Number(timestamp));
if (!Number.isFinite(Number(timestamp)) || age > toleranceSeconds) {
  return res.status(401).json({ error: 'Timestamp outside tolerance' });
}
```

Note the `Math.abs` — this rejects timestamps **in the future** too, not just stale ones, which prevents an attacker pre-signing far-future replays if they ever obtain a valid signature.

**3. Constant-time comparison**

```javascript
const a = Buffer.from(expected, 'hex');
const b = Buffer.from(receivedSig, 'hex');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return res.status(401).json({ error: 'Invalid signature' });
}
```

The explicit length check is required because `timingSafeEqual` throws on mismatched lengths — the length check itself leaks nothing useful (the attacker already knows the expected output is 64 hex chars for SHA-256).

One ordering subtlety worth keeping: the timestamp tolerance check happens **before** the HMAC comparison. This means stale requests are rejected cheaply and the timing-safe comparison only runs on plausibly fresh requests — no security impact, just avoids wasted work on obvious replays.

The middleware as sketched satisfies all three requirements as-is. Want me to add anything on top — e.g., multi-secret support for key rotation, or per-endpoint tolerance configuration?

Here's the updated middleware with secret rotation and event-ID replay protection:

```javascript
const crypto = require('crypto');

// Simple in-memory TTL cache for event IDs.
// For multi-instance deployments, swap for Redis with SET NX EX.
const seenEvents = new Map(); // eventId -> expiry (ms)
const EVENT_TTL_MS = 10 * 60 * 1000; // 10 minutes

function pruneSeenEvents() {
  const now = Date.now();
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }
}

function verifyWebhookSignature(options) {
  const {
    secrets,                   // array: [currentSecret, previousSecret]
    headerName = 'x-signature',
    toleranceSeconds = 300,
    eventHeaderName = 'x-event-id',
  } = options;

  if (!Array.isArray(secrets) || secrets.length === 0) {
    throw new Error('At least one secret required');
  }

  return (req, res, next) => {
    const rawBody = req.rawBody;
    if (!rawBody || rawBody.length === 0) {
      return res.status(400).json({ error: 'Missing body' });
    }

    const sigHeader = req.get(headerName);
    if (!sigHeader) {
      return res.status(401).json({ error: 'Missing signature' });
    }

    const parts = Object.fromEntries(
      sigHeader.split(',').map(p => p.split('=').map(s => s.trim()))
    );
    const timestamp = parts.t;
    const receivedSig = parts.v1;

    if (!timestamp || !receivedSig) {
      return res.status(401).json({ error: 'Malformed signature header' });
    }

    // Timestamp tolerance (5 min, both directions)
    const tsNum = Number(timestamp);
    if (!Number.isFinite(tsNum) || Math.abs(Date.now() / 1000 - tsNum) > toleranceSeconds) {
      return res.status(401).json({ error: 'Timestamp outside tolerance' });
    }

    // Build the signed payload once; try each secret
    const payload = Buffer.concat([
      Buffer.from(`${timestamp}.`),
      Buffer.isBuffer(rawBody) ? rawBody : Buffer.from(rawBody),
    ]);
    const received = Buffer.from(receivedSig, 'hex');
    if (received.length !== 32) { // SHA-256 output length
      return res.status(401).json({ error: 'Invalid signature' });
    }

    let valid = false;
    for (const secret of secrets) {
      const expected = crypto
        .createHmac('sha256', secret)
        .update(payload)
        .digest(); // raw Buffer, compare bytes not hex strings

      if (crypto.timingSafeEqual(expected, received)) {
        valid = true;
        break;
      }
    }

    if (!valid) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    // Event-ID replay check — only AFTER signature is verified,
    // so unauthenticated requests can't poison the cache.
    const eventId = req.get(eventHeaderName);
    if (!eventId) {
      return res.status(400).json({ error: 'Missing event ID' });
    }

    pruneSeenEvents();
    const now = Date.now();
    const existingExpiry = seenEvents.get(eventId);
    if (existingExpiry && existingExpiry > now) {
      return res.status(409).json({ error: 'Duplicate event' });
    }
    seenEvents.set(eventId, now + EVENT_TTL_MS);

    next();
  };
}

module.exports = { verifyWebhookSignature };
```

Usage:

```javascript
verifyWebhookSignature({
  secrets: [process.env.WEBHOOK_SECRET_CURRENT, process.env.WEBHOOK_SECRET_PREVIOUS],
})
```

## Design decisions worth flagging

**Secret rotation order.** Try the current secret first, then previous. Both comparisons are timing-safe, so trying multiple secrets doesn't leak which one matched. When you retire the previous secret, just drop it from the array — no code change needed.

**Replay check placement.** The event-ID check runs **after** signature verification. This is important: if it ran first, an attacker could spam fake event IDs to evict/poison the cache and deny legitimate deliveries, or probe which event IDs are real via the 409-vs-401 distinction.

**Cache scope.** The in-memory `Map` is per-process. If you run multiple instances behind a load balancer, a replay can hit a different instance and slip through. For production, replace with Redis:

```javascript
// SET key 1 NX EX 600 — atomic insert-if-absent with TTL
const inserted = await redis.set(`evt:${eventId}`, '1', 'NX', 'EX', 600);
if (!inserted) return res.status(409).json({ error: 'Duplicate event' });
```

**TTL vs. timestamp tolerance.** The 10-minute event TTL exceeds the 5-minute timestamp window deliberately — a request valid at the edge of the timestamp window stays covered by the replay cache for its full possible lifetime. If the TTL were shorter than the tolerance window, a delayed delivery could pass the timestamp check after its event-ID record expired.

**Key the cache on the event ID, not the signature.** Signatures are unique per request anyway (timestamp differs), so deduplicating on signature would never fire. Event ID is the provider's delivery identity — that's what "this is the same event" means.

Want the Redis-backed version fleshed out, or a note on handling the case where the handler fails *after* the event ID is recorded (at-least-once vs. at-most-once delivery semantics)?

```typescript
// ============================================================
// HMAC-SHA256 webhook verification middleware (TypeScript-like)
//
// Security requirements encoded here:
//   - Verify against RAW request body bytes (never re-serialized)
//   - Signed payload = `${timestamp}.${rawBody}`
//   - Reject timestamps older than 5 minutes (and in the future)
//   - Accept current OR previous secret (rotation window)
//   - Constant-time signature comparison
//   - Reject repeated event IDs for 10 minutes
//   - Replay check runs AFTER signature verification (fail closed,
//     unauthenticated requests cannot poison the dedup cache)
//   - 401 for bad signature / stale timestamp, 409 for replay
// ============================================================

import crypto from "crypto";

interface WebhookConfig {
  /** [currentSecret, previousSecret] — previous may be omitted once retired */
  secrets: string[];
  headerName?: string;      // default "x-signature"
  eventHeaderName?: string; // default "x-event-id"
  toleranceSeconds?: number; // default 300 (5 minutes)
}

interface SignatureHeader {
  timestamp: string;
  signature: string;
}

// --- Event-ID dedup store -----------------------------------------------
// In-memory for single instance. For multi-instance deployments replace with
// Redis: SET evt:<id> 1 NX EX 600 (atomic insert-if-absent with TTL).
const EVENT_TTL_MS = 10 * 60 * 1000; // 10 minutes
const seenEvents = new Map<string, number>(); // eventId -> expiry epoch ms

function pruneSeenEvents(now: number): void {
  for (const [id, expiry] of seenEvents) {
    if (expiry <= now) seenEvents.delete(id);
  }
}

// --- Helpers --------------------------------------------------------------

function parseSignatureHeader(raw: string | undefined): SignatureHeader | null {
  if (!raw) return null;
  const parts = Object.fromEntries(
    raw.split(",").map((p) => p.split("=").map((s) => s.trim()))
  );
  if (typeof parts.t !== "string" || typeof parts.v1 !== "string") return null;
  return { timestamp: parts.t, signature: parts.v1 };
}

function isTimestampFresh(timestamp: string, toleranceSeconds: number): boolean {
  const ts = Number(timestamp);
  if (!Number.isFinite(ts)) return false;
  // Math.abs: reject future timestamps too (pre-signing / clock-skew abuse)
  return Math.abs(Date.now() / 1000 - ts) <= toleranceSeconds;
}

/** Constant-time match against any accepted secret. */
function signatureMatches(payload: Buffer, received: Buffer, secrets: string[]): boolean {
  if (received.length !== 32) return false; // SHA-256 digest length
  for (const secret of secrets) {
    const expected = crypto.createHmac("sha256", secret).update(payload).digest();
    if (crypto.timingSafeEqual(expected, received)) return true;
  }
  return false;
}

// --- Middleware ------------------------------------------------------------

function verifyWebhookSignature(config: WebhookConfig) {
  const {
    secrets,
    headerName = "x-signature",
    eventHeaderName = "x-event-id",
    toleranceSeconds = 300,
  } = config;

  if (!Array.isArray(secrets) || secrets.length === 0) {
    throw new Error("At least one secret required");
  }

  return (req: Request, res: Response, next: NextFunction): void => {
    // 1. Raw body — must be captured before any body parser (express.raw)
    const rawBody: Buffer | undefined = req.rawBody;
    if (!rawBody || rawBody.length === 0) {
      res.status(400).json({ error: "Missing body" });
      return;
    }

    // 2. Parse signature header: "t=<unix-seconds>,v1=<hex>"
    const parsed = parseSignatureHeader(req.get(headerName));
    if (!parsed) {
      res.status(401).json({ error: "Missing or malformed signature" });
      return;
    }
    const { timestamp, signature } = parsed;

    // 3. Timestamp freshness — 401, checked before HMAC (cheap reject)
    if (!isTimestampFresh(timestamp, toleranceSeconds)) {
      res.status(401).json({ error: "Timestamp outside tolerance" });
      return;
    }

    // 4. HMAC over `${timestamp}.${rawBody}` — constant-time compare
    const payload = Buffer.concat([Buffer.from(`${timestamp}.`), rawBody]);
    let received: Buffer;
    try {
      received = Buffer.from(signature, "hex");
    } catch {
      res.status(401).json({ error: "Invalid signature" });
      return;
    }
    if (!signatureMatches(payload, received, secrets)) {
      res.status(401).json({ error: "Invalid signature" });
      return;
    }

    // 5. Event-ID replay check — only after authentication succeeds
    const eventId = req.get(eventHeaderName);
    if (!eventId) {
      res.status(400).json({ error: "Missing event ID" });
      return;
    }

    const now = Date.now();
    pruneSeenEvents(now);
    const existingExpiry = seenEvents.get(eventId);
    if (existingExpiry !== undefined && existingExpiry > now) {
      res.status(409).json({ error: "Duplicate event" });
      return;
    }
    seenEvents.set(eventId, now + EVENT_TTL_MS);

    // 6. Authenticated, fresh, non-replay — hand off with raw body intact
    next();
  };
}

// --- Wiring ----------------------------------------------------------------

/*
app.use(
  "/webhooks",
  express.raw({ type: "application/json", limit: "1mb" }), // preserves raw bytes
  (req, _res, next) => { req.rawBody = req.body; next(); },
  verifyWebhookSignature({
    secrets: [process.env.WEBHOOK_SECRET_CURRENT, process.env.WEBHOOK_SECRET_PREVIOUS],
  }),
  express.json(), // parse only after verification
  webhookHandler
);
*/

export { verifyWebhookSignature };
```

## Response-code contract

| Condition | Status |
|---|---|
| Missing/empty body | 400 |
| Missing or malformed signature header | 401 |
| Timestamp stale or in the future (> 5 min either direction) | **401** |
| Signature fails against all accepted secrets | **401** |
| Missing event ID | 400 |
| Event ID seen within the last 10 minutes | **409** |

## Invariants preserved from the accumulated requirements

- **Raw body only** — verification happens before `express.json()`; the parsed body is never used for signing.
- **Signed payload** is exactly `timestamp + "." + rawBody`.
- **5-minute tolerance**, enforced symmetrically via `Math.abs` (future timestamps rejected too).
- **Constant-time comparison** via `timingSafeEqual` on raw digest bytes, with an explicit length pre-check.
- **Secret rotation** — current secret tried first, previous second; both comparisons timing-safe.
- **10-minute event-ID replay window**, checked only after the signature passes so unauthenticated traffic can't poison the dedup cache.
- **Fail closed** — every failure path returns early; nothing falls through to the handler.

The one production caveat stands: the in-memory `Map` is per-process — swap in Redis (`SET NX EX 600`) if you run more than one instance.

```javascript
function normalize(value) {
  if (typeof value === "string") {
    return value.trim();
  }

  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  if (value !== null && typeof value === "object") {
    const result = {};
    for (const key of Object.keys(value)) {
      result[key] = normalize(value[key]);
    }
    return result;
  }

  return value;
}
```

Examples:

```javascript
normalize("  hello  ");
// → "hello"

normalize({ name: "  Ada  ", tags: [" a ", "b  "] });
// → { name: "Ada", tags: ["a", "b"] }

normalize({ user: { id: 1, bio: " hi " }, meta: null });
// → { user: { id: 1, bio: "hi" }, meta: null }

normalize([1, " x ", [2, " y "]]);
// → [1, "x", [2, "y"]]
```

Notes:
- Non-plain values (numbers, booleans, `null`, `undefined`, functions) pass through unchanged.
- `null` is checked before the object branch, since `typeof null === "object"`.
- Arrays are handled before the plain-object branch, since arrays are also objects.
- Class instances (e.g., `new Date()`) would be treated as plain objects and spread — if you need to exclude those, add a check like `Object.getPrototypeOf(value) === Object.prototype`.

```javascript
function normalize(value) {
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed === "" ? null : trimmed;
  }

  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  if (value !== null && typeof value === "object") {
    const result = {};
    for (const key of Object.keys(value)) {
      result[key] = normalize(value[key]);
    }
    return result;
  }

  return value;
}
```

Examples:

```javascript
normalize("  hello  ");
// → "hello"

normalize("   ");
// → null

normalize({ name: "  ", active: false, count: 0 });
// → { name: null, active: false, count: 0 }

normalize(["", " x ", 0, false]);
// → [null, "x", 0, false]
```

Notes:
- Only strings become `null` when empty after trimming — `0` and `false` are not strings, so they fall through to the pass-through branch and are preserved.
- `null` inputs still pass through unchanged (they were already `null`).

```javascript
function normalize(value) {
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed === "" ? null : trimmed;
  }

  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  if (value !== null && typeof value === "object") {
    const result = {};
    for (const key of Object.keys(value)) {
      if (value[key] === undefined) {
        continue;
      }
      result[key] = normalize(value[key]);
    }
    return result;
  }

  return value;
}
```

Examples:

```javascript
normalize({ name: " Ada ", nickname: undefined, age: 30 });
// → { name: "Ada", age: 30 }

normalize({ tags: ["a", null, undefined, " b "] });
// → { tags: ["a", null, null, "b"] }

normalize({ nested: { x: undefined, y: 0, z: false } });
// → { nested: { y: 0, z: false } }
```

Notes:
- `undefined` properties are skipped in objects, but `undefined` elements inside arrays are preserved as `null` — `Array.prototype.map` converts missing/`undefined` elements to `null` in the output, so array length and positions are kept.
- `null` entries in arrays are untouched; only object properties with `undefined` values are omitted.

```javascript
function normalize(value) {
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed === "" ? null : trimmed;
  }

  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  if (value !== null && typeof value === "object") {
    const result = {};
    for (const key of Object.keys(value)) {
      if (value[key] === undefined) {
        continue;
      }
      result[key] = normalize(value[key]);
    }
    return result;
  }

  return value;
}
```

Assertions:

```javascript
// 1. Empty/whitespace-only strings become null
console.assert(
  JSON.stringify(normalize({ a: "  ", b: " x " })) ===
    JSON.stringify({ a: null, b: "x" }),
  "empty strings become null"
);

// 2. Numeric 0 and boolean false are preserved
console.assert(
  JSON.stringify(normalize({ count: 0, active: false })) ===
    JSON.stringify({ count: 0, active: false }),
  "0 and false are preserved"
);

// 3. undefined properties are omitted, but null entries in arrays are kept
console.assert(
  JSON.stringify(normalize({ x: undefined, tags: ["a", null] })) ===
    JSON.stringify({ tags: ["a", null] }),
  "undefined omitted, null array entries kept"
);
```

