Here's a sketch using Node.js/Express-style middleware. The two critical requirements: **use the raw body** (not parsed JSON) and **timing-safe comparison**.

```js
const crypto = require('crypto');

/**
 * Middleware factory: verifies HMAC-SHA256 webhook signature.
 *
 * @param {string} secret - shared secret configured with the webhook provider
 */
function verifyWebhookSignature(secret) {
  if (!secret || typeof secret !== 'string') {
    throw new Error('Webhook secret must be a non-empty string');
  }

  return function webhookSignatureVerifier(req, res, next) {
    const signatureHeader = req.get('x-webhook-signature'); // adjust to provider spec

    if (!signatureHeader) {
      return res.status(401).json({ error: 'Missing signature header' });
    }

    // Expect format: "sha256=<hex>" (e.g., GitHub style)
    const match = /^sha256=([0-9a-f]{64})$/.exec(signatureHeader);
    if (!match) {
      return res.status(401).json({ error: 'Malformed signature header' });
    }
    const provided = match[1];

    // Compute HMAC over the RAW request body.
    // Ensure body parsing is deferred or raw body is captured (see notes below).
    const rawBody = req.rawBody; // populated by a raw-body capture step
    if (!Buffer.isBuffer(rawBody)) {
      return res.status(500).json({ error: 'Raw body unavailable' });
    }

    const expected = crypto
      .createHmac('sha256', secret)
      .update(rawBody)
      .digest('hex');

    // Timing-safe comparison to prevent timing oracles.
    const a = Buffer.from(expected, 'hex');
    const b = Buffer.from(provided, 'hex');
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    next();
  };
}

module.exports = { verifyWebhookSignature };
```

### Capturing the raw body (Express)

JSON body parsers consume the stream, so capture the raw bytes first:

```js
app.use(
  express.json({
    verify: (req, res, buf) => {
      // Only capture for webhook routes to avoid memory overhead elsewhere
      if (req.originalUrl.startsWith('/webhooks/')) {
        req.rawBody = buf;
      }
    },
  })
);

app.post('/webhooks/events', verifyWebhookSignature(process.env.WEBHOOK_SECRET), (req, res) => {
  // Signature verified; req.body is now safe to use
  res.status(204).end();
});
```

### Security notes

1. **Raw body, not re-serialized JSON** — `JSON.stringify(req.body)` will not match the original bytes (key order, whitespace, unicode escapes). Always HMAC the exact bytes received.
2. **Timing-safe compare** — `crypto.timingSafeEqual` prevents leaking how many bytes matched. The length check before it is fine since hex length is public/format-bound.
3. **Reject early, fail closed** — missing/malformed headers get `401` before any HMAC work.
4. **Constant-time on length mismatch** — the explicit length check avoids `timingSafeEqual` throwing on unequal lengths.
5. **Secret hygiene** — load from env/secret manager, never hardcode; consider rejecting if the secret is below a minimum entropy threshold.
6. **Optional hardening** — add a timestamp header check to reject replays (e.g., reject if `|now - ts| > 5 min`), and include the timestamp in the signed payload if the provider supports it.

Want a version for a different stack (Python/FastAPI, Go), or one that handles base64-encoded signatures instead of hex?

Here's the updated middleware. The HMAC is computed over `timestamp + '.' + raw_body`, with a 5-minute replay window and constant-time comparison.

```js
const crypto = require('crypto');

const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000; // 5 minutes

/**
 * Middleware factory: verifies HMAC-SHA256 webhook signature over
 * the signed payload "timestamp + '.' + raw_body".
 *
 * @param {string} secret - shared secret configured with the webhook provider
 */
function verifyWebhookSignature(secret) {
  if (!secret || typeof secret !== 'string') {
    throw new Error('Webhook secret must be a non-empty string');
  }

  return function webhookSignatureVerifier(req, res, next) {
    const signatureHeader = req.get('x-webhook-signature');
    const timestampHeader = req.get('x-webhook-timestamp');

    if (!signatureHeader || !timestampHeader) {
      return res.status(401).json({ error: 'Missing signature or timestamp header' });
    }

    // --- Timestamp validation (fail closed) ---
    const timestamp = Number(timestampHeader);
    if (!Number.isFinite(timestamp)) {
      return res.status(401).json({ error: 'Malformed timestamp' });
    }

    // Normalize: accept seconds or milliseconds epochs.
    const tsMs = timestamp < 1e12 ? timestamp * 1000 : timestamp;
    const age = Date.now() - tsMs;

    if (age > MAX_CLOCK_SKEW_MS || age < -MAX_CLOCK_SKEW_MS) {
      return res.status(401).json({ error: 'Timestamp outside allowed window' });
    }

    // --- Signature format check ---
    // Expect "sha256=<hex>"
    const match = /^sha256=([0-9a-f]{64})$/.exec(signatureHeader);
    if (!match) {
      return res.status(401).json({ error: 'Malformed signature header' });
    }
    const provided = match[1];

    // --- Raw body requirement ---
    const rawBody = req.rawBody;
    if (!Buffer.isBuffer(rawBody)) {
      return res.status(500).json({ error: 'Raw body unavailable' });
    }

    // --- Compute HMAC over timestamp + '.' + raw body ---
    const signedPayload = Buffer.concat([
      Buffer.from(timestampHeader, 'utf8'), // sign the header value as received
      Buffer.from('.', 'utf8'),
      rawBody,
    ]);

    const expected = crypto
      .createHmac('sha256', secret)
      .update(signedPayload)
      .digest('hex');

    // --- Constant-time comparison ---
    const a = Buffer.from(expected, 'hex');
    const b = Buffer.from(provided, 'hex');
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    next();
  };
}

module.exports = { verifyWebhookSignature };
```

### Key decisions

1. **Sign the timestamp as received** — we HMAC the raw header string (`timestampHeader`), not the parsed number. If the provider sends `"1700000000"` and we signed `1700000000` after parsing, formatting differences (leading zeros, `+`, exponent notation) would break verification. Match the provider's byte-exact convention.

2. **Replay window is symmetric** — rejecting only *old* timestamps lets an attacker replay a "future" timestamped payload once the clock catches up. Rejecting `age < -5min` closes that. (If your provider guarantees only past timestamps, you can tighten this.)

3. **Timestamp check before HMAC** — cheap rejection first, and it prevents an attacker from forcing expensive HMAC computations with ancient payloads. Note this ordering leaks nothing: the timestamp is public data.

4. **Constant-time compare preserved** — `crypto.timingSafeEqual` with the explicit length guard (it throws on unequal lengths, and the length check itself leaks nothing since hex length is format-bound at 64).

5. **Raw body capture unchanged** — the `express.json({ verify: ... })` raw-body capture from before still applies; the signed payload now just prepends the timestamp.

### One caveat worth flagging

