Here's the updated middleware with dual-secret rotation and a 10-minute event-ID replay cache. All prior requirements are preserved: raw body, `timestamp + '.' + raw_body` signed payload, 5-minute timestamp window, constant-time comparison.

```js
const crypto = require('crypto');

const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;   // 5 minutes
const EVENT_TTL_MS = 10 * 60 * 1000;       // 10 minutes

/**
 * Middleware factory: verifies HMAC-SHA256 webhook signature over
 * "timestamp + '.' + raw_body", accepting current or previous secret,
 * with a 10-minute event-ID replay cache.
 *
 * @param {string[]} secrets - [previousSecret, currentSecret]; either may be
 *   absent during initial setup or after rotation cleanup, but at least one
 *   must be provided.
 * @param {Object} [opts]
 * @param {Object} [opts.eventCache] - pluggable replay cache (see below).
 *   Defaults to an in-memory Map. Use Redis in multi-instance deployments.
 */
function verifyWebhookSignature(secrets, opts = {}) {
  const validSecrets = (secrets || []).filter(s => typeof s === 'string' && s.length > 0);
  if (validSecrets.length === 0) {
    throw new Error('At least one webhook secret must be provided');
  }

  const eventCache = opts.eventCache || createMemoryEventCache();

  return async function webhookSignatureVerifier(req, res, next) {
    const signatureHeader = req.get('x-webhook-signature');
    const timestampHeader = req.get('x-webhook-timestamp');
    const eventIdHeader = req.get('x-webhook-event-id');

    if (!signatureHeader || !timestampHeader || !eventIdHeader) {
      return res.status(401).json({ error: 'Missing required headers' });
    }

    // --- Timestamp validation (fail closed, symmetric window) ---
    const timestamp = Number(timestampHeader);
    if (!Number.isFinite(timestamp)) {
      return res.status(401).json({ error: 'Malformed timestamp' });
    }
    const tsMs = timestamp < 1e12 ? timestamp * 1000 : timestamp;
    const age = Date.now() - tsMs;
    if (age > MAX_CLOCK_SKEW_MS || age < -MAX_CLOCK_SKEW_MS) {
      return res.status(401).json({ error: 'Timestamp outside allowed window' });
    }

    // --- Signature format check ---
    const match = /^sha256=([0-9a-f]{64})$/.exec(signatureHeader);
    if (!match) {
      return res.status(401).json({ error: 'Malformed signature header' });
    }
    const provided = Buffer.from(match[1], 'hex');

    // --- Raw body requirement ---
    const rawBody = req.rawBody;
    if (!Buffer.isBuffer(rawBody)) {
      return res.status(500).json({ error: 'Raw body unavailable' });
    }

    // --- Signed payload: timestamp + '.' + raw body (byte-exact) ---
    const signedPayload = Buffer.concat([
      Buffer.from(timestampHeader, 'utf8'),
      Buffer.from('.', 'utf8'),
      rawBody,
    ]);

    // --- Try each secret; constant-time compare against every one ---
    let authenticated = false;
    for (const secret of validSecrets) {
      const expected = crypto
        .createHmac('sha256', secret)
        .update(signedPayload)
        .digest('hex');
      const expectedBuf = Buffer.from(expected, 'hex');

      // Compare against ALL secrets, not just until first match, so the
      // number of comparisons doesn't reveal which secret signed it.
      if (expectedBuf.length === provided.length &&
          crypto.timingSafeEqual(expectedBuf, provided)) {
        authenticated = true;
      }
    }

    if (!authenticated) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    // --- Event-ID replay check (10-minute window) ---
    // Keyed on event ID alone; the signature already binds it to this payload.
    const seen = await eventCache.checkAndSet(eventIdHeader, EVENT_TTL_MS);
    if (seen) {
      // Duplicate delivery: acknowledge so the provider stops retrying,
      // but do not reprocess.
      return res.status(200).json({ status: 'duplicate' });
    }

    next();
  };
}

// ---------------------------------------------------------------------------
// Pluggable replay cache
// ---------------------------------------------------------------------------
function createMemoryEventCache() {
  const seen = new Map(); // eventId -> expiresAt

  return {
    async checkAndSet(eventId, ttlMs) {
      const now = Date.now();

      // Lazy sweep of expired entries
      for (const [id, expiresAt] of seen) {
        if (expiresAt <= now) seen.delete(id);
      }

      const isDuplicate = seen.has(eventId);
      seen.set(eventId, now + ttlMs);
      return isDuplicate;
    },
  };
}

// Redis-backed cache for multi-instance deployments:
function createRedisEventCache(redisClient) {
  return {
    async checkAndSet(eventId, ttlMs) {
      // SET NX is atomic: returns OK only if the key did not exist.
      const result = await redisClient.set(
        `webhook:seen:${eventId}`,
        '1',
        'PX', ttlMs,
        'NX'
      );
      return result === null; // null => key existed => duplicate
    },
  };
}

module.exports = { verifyWebhookSignature, createMemoryEventCache, createRedisEventCache };
```

### Design decisions

1. **Compare against every secret, not short-circuit** — if we stopped at the first match, an attacker observing response timing could infer *which* secret (current vs. previous) signed a payload, narrowing a brute-force target. Computing all HMACs and comparing all keeps the work factor uniform. (With only two secrets the leak is small, but it's free to close.)

2. **Replay cache checked *after* signature verification** — an unauthenticated attacker must not be able to poison the cache with arbitrary event IDs and cause legitimate deliveries to be rejected as duplicates. Only authenticated events get recorded.

3. **Duplicates return `200`, not `409`** — webhook providers retry on non-2xx. A duplicate is a *successful, already-processed* delivery; acknowledging it stops retry storms. The response body lets your own tooling distinguish it.

4. **Event ID keyed alone, not `(eventId, signature)`** — the signature check already binds the event ID to the exact payload, so a duplicate ID with a different body would have failed signature verification before reaching the cache. Keying on ID alone keeps the cache small.

5. **TTL (10 min) > timestamp window (5 min)** — deliberately. A replayed event within the timestamp window is caught by the cache; the extra margin covers clock skew between your instances and the provider. If the cache TTL were shorter than the signature window, replays would slip through.

6. **Memory cache is single-instance only** — the `Map` won't dedupe across horizontally scaled replicas. Use the Redis variant (atomic `SET NX PX`) in production; it's race-free even under concurrent duplicate deliveries.

7. **Rotation hygiene** — keep exactly `[previous, current]`. Once the provider confirms full cutover (all recent deliveries verify against the new secret), drop the old one; accepting indefinitely many old secrets widens the attack surface.

### Accumulated security requirements (running list)

- ✅ HMAC-SHA256 over the **raw request body** (never re-serialized JSON)
- ✅ Signed payload is `timestamp + '.' + raw_body`, byte-exact header value
- ✅ Reject timestamps older than 5 minutes (symmetric window, fail closed)
- ✅ Constant-time comparison (`timingSafeEqual` + length guard)
- ✅ Accept **current or previous secret** only; compare against all, no short-circuit
- ✅ Reject repeated event IDs for **10 minutes** (post-authentication, atomic check-and-set)

