```ts
// webhook-verification.ts — final

import { createHmac, timingSafeEqual } from "crypto";

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;   // reject timestamps older than 5 min
const EVENT_TTL_MS = 10 * 60 * 1000;       // reject repeated event IDs for 10 min

interface EventCache {
  /** Atomic check-and-set. Returns true if the eventId was already seen. */
  checkAndSet(eventId: string, ttlMs: number): Promise<boolean>;
}

interface VerifyOptions {
  /** [previousSecret, currentSecret] — at least one required. */
  secrets: string[];
  eventCache: EventCache;
}

// ---------------------------------------------------------------------------
// Middleware factory
// ---------------------------------------------------------------------------
function makeWebhookVerifier(opts: VerifyOptions) {
  const secrets = opts.secrets.filter(s => s.length > 0);
  if (secrets.length === 0) throw new Error("At least one secret required");

  return async function verifyWebhook(
    req: Request,
    res: Response,
    next: NextFunction
  ): Promise<void> {
    const signatureHeader = req.header("x-webhook-signature");
    const timestampHeader = req.header("x-webhook-timestamp");
    const eventId = req.header("x-webhook-event-id");

    // --- Fail closed on missing headers ---
    if (!signatureHeader || !timestampHeader || !eventId) {
      return res.status(401).json({ error: "Missing required headers" });
    }

    // --- Timestamp validation: reject stale (401) ---
    const timestamp = Number(timestampHeader);
    if (!Number.isFinite(timestamp)) {
      return res.status(401).json({ error: "Malformed timestamp" });
    }
    const tsMs = timestamp < 1e12 ? timestamp * 1000 : timestamp;
    const age = Date.now() - tsMs;
    if (age > MAX_CLOCK_SKEW_MS || age < -MAX_CLOCK_SKEW_MS) {
      return res.status(401).json({ error: "Timestamp outside allowed window" });
    }

    // --- Signature format check ---
    const match = /^sha256=([0-9a-f]{64})$/.exec(signatureHeader);
    if (!match) {
      return res.status(401).json({ error: "Malformed signature header" });
    }
    const provided = Buffer.from(match[1], "hex");

    // --- Raw body requirement (captured pre-parse, never re-serialized) ---
    if (!Buffer.isBuffer(req.rawBody)) {
      return res.status(500).json({ error: "Raw body unavailable" });
    }

    // --- Signed payload: timestamp + '.' + raw body (byte-exact) ---
    const signedPayload = Buffer.concat([
      Buffer.from(timestampHeader, "utf8"),
      Buffer.from(".", "utf8"),
      req.rawBody,
    ]);

    // --- HMAC against ALL secrets; no short-circuit (uniform timing) ---
    let authenticated = false;
    for (const secret of secrets) {
      const expected = Buffer.from(
        createHmac("sha256", secret).update(signedPayload).digest("hex"),
        "hex"
      );
      if (
        expected.length === provided.length &&
        timingSafeEqual(expected, provided)
      ) {
        authenticated = true;
      }
    }

    if (!authenticated) {
      return res.status(401).json({ error: "Invalid signature" });
    }

    // --- Replay check: AFTER auth, so the cache can't be poisoned ---
    const isReplay = await opts.eventCache.checkAndSet(eventId, EVENT_TTL_MS);
    if (isReplay) {
      return res.status(409).json({ error: "Duplicate event" });
    }

    next();
  };
}

// ---------------------------------------------------------------------------
// Raw body capture (must run BEFORE JSON parsing)
// ---------------------------------------------------------------------------
app.use(
  express.json({
    verify: (req, res, buf) => {
      if (req.originalUrl.startsWith("/webhooks/")) {
        req.rawBody = buf;
      }
    },
  })
);

// ---------------------------------------------------------------------------
// Event caches
// ---------------------------------------------------------------------------
function createMemoryEventCache(): EventCache {
  const seen = new Map<string, number>(); // eventId -> expiresAt
  return {
    async checkAndSet(eventId, ttlMs) {
      const now = Date.now();
      for (const [id, exp] of seen) if (exp <= now) seen.delete(id);
      const isDup = seen.has(eventId);
      seen.set(eventId, now + ttlMs);
      return isDup;
    },
  };
}

function createRedisEventCache(redis: RedisClient): EventCache {
  return {
    async checkAndSet(eventId, ttlMs) {
      // Atomic SET NX PX — race-free across instances.
      const result = await redis.set(
        `webhook:seen:${eventId}`, "1",
        "PX", ttlMs, "NX"
      );
      return result === null; // null => key existed => duplicate
    },
  };
}

// ---------------------------------------------------------------------------
// Wiring
// ---------------------------------------------------------------------------
app.post(
  "/webhooks/events",
  makeWebhookVerifier({
    secrets: [process.env.WEBHOOK_SECRET_PREVIOUS!, process.env.WEBHOOK_SECRET_CURRENT!],
    eventCache: createRedisEventCache(redis), // memory cache for single-instance only
  }),
  handleEvent
);
```

### Status code contract

| Condition | Status |
|---|---|
| Missing/malformed headers | **401** |
| Timestamp outside 5-minute window | **401** |
| Signature fails against all accepted secrets | **401** |
| Valid signature, event ID seen within 10 min | **409** |
| Raw body unavailable (server misconfiguration) | **500** |

Note: a 409 will trigger provider retries — that's intentional per your spec, but ensure your handler is idempotent anyway, since retries can race the cache TTL.

### Final requirements checklist

- ✅ HMAC-SHA256 over the **raw request body** (never re-serialized JSON)
- ✅ Signed payload is `timestamp + '.' + raw_body`, byte-exact header value
- ✅ Reject timestamps older than 5 minutes — symmetric window, fail closed → **401**
- ✅ Constant-time comparison (`timingSafeEqual` + length guard)
- ✅ Accept **current or previous secret**; compare against all, no short-circuit
- ✅ Reject repeated event IDs for **10 minutes** → **409**, checked post-authentication, atomic check-and-set
- ✅ Cache TTL (10 min) > timestamp window (5 min) so replays can't slip through

# normalize(value)

```javascript
function normalize(value) {
  // Trim strings
  if (typeof value === "string") {
    return value.trim();
  }

  // Recursively handle arrays
  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  // Recursively handle plain objects only
  if (isPlainObject(value)) {
    const result = {};
    for (const key of Object.keys(value)) {
      result[key] = normalize(value[key]);
    }
    return result;
  }

  // Everything else (numbers, booleans, null, undefined, etc.) passes through
  return value;
}

function isPlainObject(value) {
  return Object.prototype.toString.call(value) === "[object Object]";
}
```

## Notes

- **Strings** are trimmed and returned.
- **Arrays** return a new array with each element normalized (original is not mutated).
- **Plain objects** return a new object with each value normalized. `isPlainObject` uses `Object.prototype.toString` so class instances (e.g., `new Date()`, `new Map()`) are **not** treated as plain objects and pass through untouched — this avoids accidentally destroying things like Dates.
- **Primitives** (`number`, `boolean`, `null`, `undefined`) are returned as-is.

## Example

```javascript
normalize({
  name: "  Alice  ",
  tags: [" a ", "b"],
  meta: { note: "  hi  " },
  created: new Date(), // untouched
});
// → { name: "Alice", tags: ["a", "b"], meta: { note: "hi" }, created: <Date> }
```

If you'd prefer class instances to also be deep-normalized, or want `null`/`undefined` values dropped from objects, let me know and I can adjust.

# normalize(value) — updated

```javascript
function normalize(value) {
  // Trim strings; empty strings become null
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed === "" ? null : trimmed;
  }

  // Recursively handle arrays
  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  // Recursively handle plain objects only
  if (isPlainObject(value)) {
    const result = {};
    for (const key of Object.keys(value)) {
      result[key] = normalize(value[key]);
    }
    return result;
  }

  // Everything else passes through unchanged
  return value;
}

function isPlainObject(value) {
  return Object.prototype.toString.call(value) === "[object Object]";
}
```

## Key points

- **Empty strings → `null`**: a string that is empty or only whitespace (e.g., `"  "`) becomes `null`.
- **`0` and `false` preserved**: they fall into the final `return value` branch and are returned as-is — no truthiness checks anywhere, so they're never coerced or dropped.
- Same recursion rules as before: arrays and plain objects are deep-copied into normalized results; class instances pass through untouched.

## Example

```javascript
normalize({
  name: "  Alice  ",
  nickname: "   ",      // → null
  age: 0,              // → 0 (preserved)
  active: false,       // → false (preserved)
  tags: [" a ", ""],   // → ["a", null]
});
// → { name: "Alice", nickname: null, age: 0, active: false, tags: ["a", null] }
```

# normalize(value) — updated

```javascript
function normalize(value) {
  // Trim strings; empty strings become null
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed === "" ? null : trimmed;
  }

  // Recursively handle arrays — null entries are preserved
  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  // Recursively handle plain objects — undefined properties are omitted
  if (isPlainObject(value)) {
    const result = {};
    for (const key of Object.keys(value)) {
      const normalized = normalize(value[key]);
      if (normalized !== undefined) {
        result[key] = normalized;
      }
    }
    return result;
  }

  // Everything else passes through unchanged
  return value;
}

function isPlainObject(value) {
  return Object.prototype.toString.call(value) === "[object Object]";
}
```

## Key points

- **`undefined` properties omitted**: if a property's normalized value is `undefined`, the key is dropped from the output object entirely.
- **`null` preserved everywhere**: `null` values in objects are kept, and `null` entries in arrays are kept (arrays use `map`, which never removes elements — including the `null`s produced by empty-string trimming).
- **`0` and `false` still preserved**: the omission check is strictly `!== undefined`, so falsy-but-meaningful values survive.

## Example

```javascript
normalize({
  name: "  Alice  ",
  nickname: "   ",       // → null (kept)
  age: 0,                // → 0 (kept)
  active: false,         // → false (kept)
  temp: undefined,       // → key omitted entirely
  tags: [" a ", "", undefined], // → ["a", null, undefined] (length preserved)
});
// → { name: "Alice", nickname: null, age: 0, active: false,
//     tags: ["a", null, undefined] }
```

Note: `undefined` entries *inside arrays* are kept as-is, since removing them would change array length/indices — only object properties are dropped. Let me know if you'd like array `undefined`s handled differently.

# Final normalize(value)

```javascript
function normalize(value) {
  // Trim strings; empty strings become null
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed === "" ? null : trimmed;
  }

  // Recursively handle arrays — null entries are preserved
  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  // Recursively handle plain objects — undefined properties are omitted
  if (isPlainObject(value)) {
    const result = {};
    for (const key of Object.keys(value)) {
      const normalized = normalize(value[key]);
      if (normalized !== undefined) {
        result[key] = normalized;
      }
    }
    return result;
  }

  // Everything else passes through unchanged
  return value;
}

function isPlainObject(value) {
  return Object.prototype.toString.call(value) === "[object Object]";
}
```

## Assertions

```javascript
// 1. Empty strings become null; 0 and false are preserved
console.assert(
  JSON.stringify(normalize({ a: "  ", b: 0, c: false })) ===
    '{"a":null,"b":0,"c":false}',
  "empty string → null, 0 and false preserved"
);

// 2. Undefined properties are omitted from objects
console.assert(
  !("missing" in normalize({ missing: undefined, kept: " x " })),
  "undefined property omitted"
);

// 3. Null entries are NOT removed from arrays
console.assert(
  JSON.stringify(normalize([" a ", "", null])) === '["a",null,null]',
  "null entries preserved in arrays"
);
```

All three assertions pass silently with the final function above.

