# HMAC-SHA256 Webhook Signature Verification Middleware

Key requirements: use the **raw** body (not parsed JSON), compare with a **timing-safe** function, and read the secret from config — never hardcode it.

## Express (Node.js)

```js
const crypto = require('crypto');

// Capture the raw body BEFORE any JSON parsing
app.use('/webhooks', express.raw({ type: '*/*' }));

function verifyWebhookSignature(secretEnvVar = 'WEBHOOK_SECRET') {
  return (req, res, next) => {
    const secret = process.env[secretEnvVar];
    if (!secret) {
      // Fail closed: misconfiguration must not silently allow requests
      return res.status(500).json({ error: 'Server misconfigured' });
    }

    const signature = req.get('X-Signature-256'); // e.g. "sha256=abc123..."
    if (!signature || !signature.startsWith('sha256=')) {
      return res.status(401).json({ error: 'Missing or malformed signature' });
    }

    // req.body must be the raw Buffer — never JSON.stringify(req.body),
    // since re-serialization can change key order/whitespace and break the HMAC
    const expected =
      'sha256=' +
      crypto.createHmac('sha256', secret).update(req.body).digest('hex');

    const sigBuf = Buffer.from(signature);
    const expBuf = Buffer.from(expected);

    // timingSafeEqual throws on length mismatch — check first
    if (sigBuf.length !== expBuf.length ||
        !crypto.timingSafeEqual(sigBuf, expBuf)) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    next();
  };
}

app.post('/webhooks/events', verifyWebhookSignature(), (req, res) => {
  const event = JSON.parse(req.body.toString('utf8')); // parse only after verification
  // ... handle event
  res.sendStatus(200);
});
```

## Optional: replay protection

Signatures alone don't stop replayed requests. Add a timestamp check:

```js
const ts = Number(req.get('X-Signature-Timestamp'));
if (!ts || Math.abs(Date.now() / 1000 - ts) > 300) {
  return res.status(401).json({ error: 'Stale timestamp' });
}
// Then HMAC over `${ts}.${rawBody}` instead of just the body
```

## Common pitfalls

- **Body parser ordering**: `express.json()` must not run before this middleware on the webhook route, or the raw bytes are lost.
- **Never `JSON.stringify(req.body)`** to recompute the HMAC — use the original bytes.
- **Always use `crypto.timingSafeEqual`** — `===` leaks timing information.
- **Fail closed** on missing secret, missing header, or malformed input.
- Use a dedicated, high-entropy secret per webhook provider, stored in a secrets manager/env var, and support rotation.

# HMAC-SHA256 Verification with Timestamped Payload

The HMAC is computed over `timestamp + '.' + raw_body`, timestamps older than 5 minutes are rejected, and all comparisons are constant-time.

```js
const crypto = require('crypto');
const express = require('express');

const app = express();

// Capture the raw body BEFORE any JSON parsing on webhook routes
app.use('/webhooks', express.raw({ type: '*/*' }));

const MAX_TIMESTAMP_AGE_SECONDS = 300; // 5 minutes

function verifyWebhookSignature(secretEnvVar = 'WEBHOOK_SECRET') {
  return (req, res, next) => {
    const secret = process.env[secretEnvVar];
    if (!secret) {
      // Fail closed: misconfiguration must not silently allow requests
      return res.status(500).json({ error: 'Server misconfigured' });
    }

    const signature = req.get('X-Signature-256');   // e.g. "sha256=abc123..."
    const timestamp = req.get('X-Signature-Timestamp'); // Unix seconds

    if (!signature || !signature.startsWith('sha256=') || !timestamp) {
      return res.status(401).json({ error: 'Missing signature or timestamp' });
    }

    // --- Replay protection: reject stale or future-skewed timestamps ---
    const ts = Number(timestamp);
    if (!Number.isFinite(ts) || !/^\d+$/.test(timestamp)) {
      return res.status(401).json({ error: 'Malformed timestamp' });
    }

    const nowSeconds = Math.floor(Date.now() / 1000);
    if (Math.abs(nowSeconds - ts) > MAX_TIMESTAMP_AGE_SECONDS) {
      return res.status(401).json({ error: 'Timestamp outside allowed window' });
    }

    // --- Recompute HMAC over "timestamp.raw_body" ---
    // req.body must be the raw Buffer — never JSON.stringify(req.body),
    // since re-serialization can change key order/whitespace and break the HMAC
    const signedPayload = Buffer.concat([
      Buffer.from(timestamp, 'utf8'),
      Buffer.from('.', 'utf8'),
      req.body,
    ]);

    const expected =
      'sha256=' +
      crypto.createHmac('sha256', secret).update(signedPayload).digest('hex');

    // --- Constant-time comparison ---
    const sigBuf = Buffer.from(signature, 'utf8');
    const expBuf = Buffer.from(expected, 'utf8');

    // timingSafeEqual throws on length mismatch — check length first
    if (sigBuf.length !== expBuf.length ||
        !crypto.timingSafeEqual(sigBuf, expBuf)) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    next();
  };
}

app.post('/webhooks/events', verifyWebhookSignature(), (req, res) => {
  const event = JSON.parse(req.body.toString('utf8')); // parse only after verification
  // ... handle event
  res.sendStatus(200);
});
```

## Notes

- **Signed payload format**: `timestamp` (exact header string, not the parsed number) + `'.'` + raw body bytes. Using the original header string avoids mismatches from formatting differences (e.g. leading zeros).
- **Timestamp window**: `Math.abs(now - ts) > 300` rejects both stale timestamps *and* timestamps too far in the future (clock-skew attacks / precomputed future signatures).
- **Constant-time comparison**: `crypto.timingSafeEqual` on equal-length buffers; the length check happens first since it throws on mismatched lengths. Length itself is not secret here (hex digest of SHA-256 is fixed-length for valid input).
- **Fail closed** on every malformed input: missing headers, non-numeric timestamp, bad signature prefix.
- **Ordering matters**: `express.json()` must not run before this middleware on the webhook route, or the raw bytes are lost.
- Keep the secret in env/secrets manager, unique per provider, and support rotation.

# HMAC Verification with Secret Rotation + Replay Protection

Accepts signatures from **either the current or previous secret** (rotation window), and rejects **repeated event IDs for 10 minutes** to block replays within the timestamp window.

```js
const crypto = require('crypto');
const express = require('express');
const Redis = require('ioredis'); // shared store — see notes for in-memory alternative

const app = express();
const redis = new Redis(process.env.REDIS_URL);

// Capture the raw body BEFORE any JSON parsing on webhook routes
app.use('/webhooks', express.raw({ type: '*/*' }));

const MAX_TIMESTAMP_AGE_SECONDS = 300;        // 5 minutes
const EVENT_ID_TTL_SECONDS = 600;             // 10 minutes
const EVENT_ID_PATTERN = /^[A-Za-z0-9_-]{1,128}$/; // strict format, prevents cache-key abuse

function verifyWebhookSignature() {
  return async (req, res, next) => {
    // --- Load rotation secrets; fail closed if none configured ---
    const secrets = [process.env.WEBHOOK_SECRET_CURRENT,
                     process.env.WEBHOOK_SECRET_PREVIOUS].filter(Boolean);
    if (secrets.length === 0) {
      return res.status(500).json({ error: 'Server misconfigured' });
    }

    const signature = req.get('X-Signature-256');      // "sha256=abc123..."
    const timestamp = req.get('X-Signature-Timestamp'); // Unix seconds
    const eventId   = req.get('X-Event-Id');

    if (!signature || !signature.startsWith('sha256=') || !timestamp || !eventId) {
      return res.status(401).json({ error: 'Missing signature, timestamp, or event ID' });
    }

    // --- Replay protection, layer 1: timestamp window ---
    if (!/^\d+$/.test(timestamp)) {
      return res.status(401).json({ error: 'Malformed timestamp' });
    }
    const ts = Number(timestamp);
    const nowSeconds = Math.floor(Date.now() / 1000);
    if (Math.abs(nowSeconds - ts) > MAX_TIMESTAMP_AGE_SECONDS) {
      return res.status(401).json({ error: 'Timestamp outside allowed window' });
    }

    // --- Recompute HMAC over "timestamp.raw_body" ---
    // req.body must be the raw Buffer — never JSON.stringify(req.body)
    const signedPayload = Buffer.concat([
      Buffer.from(timestamp, 'utf8'),
      Buffer.from('.', 'utf8'),
      req.body,
    ]);

    // --- Constant-time comparison against current OR previous secret ---
    // Always compute both to avoid leaking which secret is active via timing
    const sigBuf = Buffer.from(signature, 'utf8');
    let matched = false;
    for (const secret of secrets) {
      const expected = 'sha256=' +
        crypto.createHmac('sha256', secret).update(signedPayload).digest('hex');
      const expBuf = Buffer.from(expected, 'utf8');
      if (sigBuf.length === expBuf.length &&
          crypto.timingSafeEqual(sigBuf, expBuf)) {
        matched = true; // don't break: keep timing uniform
      }
    }
    if (!matched) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    // --- Replay protection, layer 2: event ID deduplication (10 min TTL) ---
    if (!EVENT_ID_PATTERN.test(eventId)) {
      return res.status(401).json({ error: 'Malformed event ID' });
    }
    // Atomic check-and-set: NX ensures only the first delivery wins.
    // Signature is verified BEFORE this, so attackers can't poison the cache
    // with arbitrary event IDs.
    const key = `webhook:event:${eventId}`;
    const wasNew = await redis.set(key, '1', 'EX', EVENT_ID_TTL_SECONDS, 'NX');
    if (wasNew === null) {
      return res.status(409).json({ error: 'Duplicate event' });
    }

    next();
  };
}

app.post('/webhooks/events', verifyWebhookSignature(), (req, res) => {
  const event = JSON.parse(req.body.toString('utf8')); // parse only after verification
  // ... handle event
  res.sendStatus(200);
});
```

## In-memory fallback (single-instance only)

```js
const seen = new Map(); // eventId -> expiry
function isDuplicate(eventId) {
  const now = Date.now();
  if (seen.size > 100_000) { // bound memory: purge expired entries
    for (const [id, exp] of seen) if (exp <= now) seen.delete(id);
  }
  if ((seen.get(eventId) ?? 0) > now) return true;
  seen.set(eventId, now + EVENT_ID_TTL_SECONDS * 1000);
  return false;
}
```

## Notes

- **Rotation**: set both `WEBHOOK_SECRET_CURRENT` and `WEBHOOK_SECRET_PREVIOUS` during rotation; remove the previous one once the sender has fully switched over. Both candidates are always HMAC'd so timing doesn't reveal which secret matched.
- **Why two replay layers**: the 5-minute timestamp window alone still allows replays *within* those 5 minutes — the event-ID dedup closes that gap. The 10-minute TTL comfortably outlives the timestamp window.
- **Ordering is deliberate**: signature is verified *before* the dedup write, so unauthenticated requests can't burn event IDs and cause denial of service against legitimate retries.
- **Atomicity**: `SET ... NX EX` is a single atomic Redis op — safe under concurrent duplicate deliveries. The in-memory version is only safe for a single process.
- **Fail closed** on missing secrets, malformed headers, bad timestamps, and invalid event ID format.
- **Body parsing**: `express.json()` must not run before this middleware on webhook routes, or the raw bytes are lost.

# Final Middleware — TypeScript Pseudocode

Consolidated requirements: HMAC-SHA256 over `timestamp + '.' + raw_body`, current **or** previous secret, 5-minute timestamp window, 10-minute event-ID dedup, constant-time comparison, fail closed. **401** for bad signature/stale timestamp, **409** for replay.

```typescript
import { createHmac, timingSafeEqual } from 'crypto';

// ---------- Configuration ----------
const MAX_TIMESTAMP_AGE_SECONDS = 300;   // 5 minutes
const EVENT_ID_TTL_SECONDS      = 600;   // 10 minutes
const EVENT_ID_PATTERN          = /^[A-Za-z0-9_-]{1,128}$/;

interface Request {
  headers: Record<string, string | undefined>;
  rawBody: Buffer;   // MUST be the untouched raw bytes — never re-serialized JSON
}
interface Response {
  status(code: number): Response;
  json(body: object): void;
}
type Next = () => void;

// Shared atomic store (e.g., Redis SET key 1 EX ttl NX)
interface DedupStore {
  setIfAbsent(key: string, ttlSeconds: number): Promise<boolean>; // true = first seen
}

// ---------- Middleware ----------
function verifyWebhookSignature(store: DedupStore) {
  return async (req: Request, res: Response, next: Next): Promise<void> => {

    // Load rotation secrets; fail closed if none configured
    const secrets = [process.env.WEBHOOK_SECRET_CURRENT,
                     process.env.WEBHOOK_SECRET_PREVIOUS]
      .filter((s): s is string => Boolean(s));
    if (secrets.length === 0) {
      return res.status(500).json({ error: 'Server misconfigured' });
    }

    const signature = req.headers['x-signature-256'];        // "sha256=<hex>"
    const timestamp = req.headers['x-signature-timestamp'];  // Unix seconds
    const eventId   = req.headers['x-event-id'];

    if (!signature?.startsWith('sha256=') || !timestamp || !eventId) {
      return res.status(401).json({ error: 'Missing signature, timestamp, or event ID' });
    }

    // --- Timestamp window: stale OR future-skewed -> 401 ---
    if (!/^\d+$/.test(timestamp)) {
      return res.status(401).json({ error: 'Malformed timestamp' });
    }
    const nowSeconds = Math.floor(Date.now() / 1000);
    if (Math.abs(nowSeconds - Number(timestamp)) > MAX_TIMESTAMP_AGE_SECONDS) {
      return res.status(401).json({ error: 'Stale timestamp' });
    }

    // --- HMAC over "timestamp.raw_body" using the exact header string ---
    const signedPayload = Buffer.concat([
      Buffer.from(timestamp, 'utf8'),
      Buffer.from('.', 'utf8'),
      req.rawBody,
    ]);

    // --- Constant-time check against current OR previous secret ---
    // Always evaluate every candidate: no early break, so timing
    // does not reveal which secret matched.
    const sigBuf = Buffer.from(signature, 'utf8');
    let matched = false;
    for (const secret of secrets) {
      const expected = 'sha256=' +
        createHmac('sha256', secret).update(signedPayload).digest('hex');
      const expBuf = Buffer.from(expected, 'utf8');
      if (sigBuf.length === expBuf.length && timingSafeEqual(sigBuf, expBuf)) {
        matched = true;
      }
    }
    if (!matched) {
      return res.status(401).json({ error: 'Invalid signature' });
    }

    // --- Replay dedup: signature verified FIRST so attackers can't
    //     poison the cache with arbitrary event IDs ---
    if (!EVENT_ID_PATTERN.test(eventId)) {
      return res.status(401).json({ error: 'Malformed event ID' });
    }
    const isFirstDelivery = await store.setIfAbsent(
      `webhook:event:${eventId}`, EVENT_ID_TTL_SECONDS);
    if (!isFirstDelivery) {
      return res.status(409).json({ error: 'Duplicate event' });
    }

    next();
  };
}
```

## Status code summary

| Condition | Status |
|---|---|
| Missing/malformed signature, timestamp, or event ID | 401 |
| Timestamp outside ±5-minute window | 401 |
| HMAC matches neither current nor previous secret | 401 |
| Event ID already seen within 10 minutes | 409 |
| No secrets configured (fail closed) | 500 |

## Invariants to preserve

- `rawBody` is the original request bytes; no JSON parser runs before this middleware.
- Signed payload uses the **exact timestamp header string**, not the parsed number.
- All signature comparisons use `timingSafeEqual` on equal-length buffers; every candidate secret is always evaluated.
- Dedup write is atomic (`SET NX EX`) and happens **only after** signature verification.
- Every failure path returns immediately — no fall-through to `next()`.

```javascript
function normalize(value) {
  if (typeof value === "string") {
    return value.trim();
  }
  if (Array.isArray(value)) {
    return value.map(normalize);
  }
  if (value !== null && typeof value === "object" && Object.getPrototypeOf(value) === Object.prototype) {
    const result = {};
    for (const key of Object.keys(value)) {
      result[key] = normalize(value[key]);
    }
    return result;
  }
  return value;
}
```

**How it works:**

- **Strings** — trimmed and returned.
- **Arrays** — each element is recursively normalized via `map`.
- **Plain objects** — each value is recursively normalized into a new object. The `Object.getPrototypeOf(value) === Object.prototype` check ensures only plain objects are transformed, so class instances, `Date`s, `Map`s, etc. pass through untouched.
- **Everything else** (numbers, booleans, `null`, `undefined`) — returned as-is.

**Example:**

```javascript
normalize({
  name: "  Alice  ",
  tags: [" admin ", "user "],
  meta: { note: "  hello " },
  count: 3
});
// { name: "Alice", tags: ["admin", "user"], meta: { note: "hello" }, count: 3 }
```

Note: this doesn't handle circular references — if your data might contain cycles, you'd need a `WeakSet` to track visited objects.

```javascript
function normalize(value) {
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed === "" ? null : trimmed;
  }
  if (Array.isArray(value)) {
    return value.map(normalize);
  }
  if (value !== null && typeof value === "object" && Object.getPrototypeOf(value) === Object.prototype) {
    const result = {};
    for (const key of Object.keys(value)) {
      result[key] = normalize(value[key]);
    }
    return result;
  }
  return value;
}
```

**What changed:**

- After trimming, an empty string (`""` or whitespace-only like `"   "`) becomes `null`.
- The final `return value` branch is untouched, so `0` and `false` pass through as-is — the empty-string check only applies to actual strings, never to other falsy values.

**Example:**

```javascript
normalize({
  name: "  Alice  ",
  nickname: "   ",
  age: 0,
  active: false,
  tags: ["", " user "]
});
// { name: "Alice", nickname: null, age: 0, active: false, tags: [null, "user"] }
```

The key distinction: the `null` conversion happens *inside* the string branch, so falsy non-strings are never affected.

```javascript
function normalize(value) {
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed === "" ? null : trimmed;
  }
  if (Array.isArray(value)) {
    return value.map(normalize);
  }
  if (value !== null && typeof value === "object" && Object.getPrototypeOf(value) === Object.prototype) {
    const result = {};
    for (const key of Object.keys(value)) {
      const normalized = normalize(value[key]);
      if (normalized !== undefined) {
        result[key] = normalized;
      }
    }
    return result;
  }
  return value;
}
```

**What changed:**

- **Objects:** after normalizing each value, the key is only added to the result if the normalized value isn't `undefined`. This drops properties that were `undefined` in the input.
- **Arrays:** still use `map`, which preserves length and positions — so `undefined` and `null` entries stay in place (note: `map` skips holes in sparse arrays, leaving them as holes, which also preserves the array's shape).

**Example:**

```javascript
normalize({
  name: "  Alice ",
  nickname: "   ",
  missing: undefined,
  age: 0,
  tags: ["", undefined, " user "]
});
// { name: "Alice", nickname: null, age: 0, tags: [null, undefined, "user"] }
```

The distinction matters: `undefined` signals "absent" for object properties (omitted), but arrays are positional — removing entries would shift indices, so they're kept as-is.

```javascript
function normalize(value) {
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed === "" ? null : trimmed;
  }
  if (Array.isArray(value)) {
    return value.map(normalize);
  }
  if (value !== null && typeof value === "object" && Object.getPrototypeOf(value) === Object.prototype) {
    const result = {};
    for (const key of Object.keys(value)) {
      const normalized = normalize(value[key]);
      if (normalized !== undefined) {
        result[key] = normalized;
      }
    }
    return result;
  }
  return value;
}

// Assertion 1: empty/whitespace-only strings become null (recursively)
console.assert(
  JSON.stringify(normalize({ a: "   ", b: ["", " x "] })) ===
  JSON.stringify({ a: null, b: [null, "x"] }),
  "empty strings should become null"
);

// Assertion 2: numeric 0 and boolean false are preserved
console.assert(
  JSON.stringify(normalize({ count: 0, active: false, list: [0, false] })) ===
  JSON.stringify({ count: 0, active: false, list: [0, false] }),
  "0 and false must pass through unchanged"
);

// Assertion 3: undefined object properties are omitted, but array entries are kept
const result = normalize({ keep: "v", drop: undefined, arr: [undefined, "y"] });
console.assert(
  !("drop" in result) && result.arr.length === 2 && result.arr[0] === undefined,
  "undefined omitted from objects, preserved in arrays"
);
```

**Coverage of the three corrections:**

1. **Empty string → `null`:** verifies both a top-level object property and nested array elements, confirming the conversion happens recursively.
2. **`0` and `false` preserved:** confirms falsy non-strings survive in both objects and arrays — they never hit the `null` conversion.
3. **`undefined` handling:** uses `"drop" in result` (not just value comparison) to prove the key is truly absent, while `arr.length === 2` proves the array's positional entries were not removed.

